/*
 * Generates internal/mosh/terminal/widthtable.go from the stock parity
 * oracle's wcwidth(3): glibc 2.39 in Ubuntu 24.04 with LC_CTYPE=C.UTF-8, the
 * locale the parity Docker image uses for mosh-client and mosh-terminal-ref.
 *
 * mosh 1.4.0 calls wcwidth() for every non-Latin-1 code point and treats -1
 * as unprintable, 0 as combining/zero-width, and 1 or 2 as printable columns.
 * Go's unicode.IsPrint and x/text/width are not a substitute: they disagree
 * with glibc for Zs separators, private-use code points, Hangul Jamo, and
 * unassigned code points.
 *
 * See the "wcwidth semantics" section of README.md in this directory for the
 * regeneration command. The table records only ranges whose width is not 1. Every code point outside
 * the ranges is width 1, matching glibc. Code point 0 is recorded as width 0
 * but RuneWidth special-cases it to -1 before the lookup, because stock mosh
 * handles NUL before calling wcwidth.
 */

#define _XOPEN_SOURCE 700
#include <locale.h>
#include <stdio.h>
#include <wchar.h>

int main(void)
{
  if (setlocale(LC_CTYPE, "C.UTF-8") == NULL) {
    fprintf(stderr, "C.UTF-8 locale is unavailable\n");
    return 1;
  }

  printf("// Code generated by testdata/parity/harness/wcwidth_gen.c; DO NOT EDIT.\n");
  printf("\n");
  printf("package terminal\n");
  printf("\n");
  printf("// wcwidthRange is one closed interval of code points with the same\n");
  printf("// glibc wcwidth(3) result.\n");
  printf("type wcwidthRange struct {\n");
  printf("\tlo, hi rune\n");
  printf("\twidth  int8\n");
  printf("}\n");
  printf("\n");
  printf("// wcwidthRanges records every code point whose glibc 2.39 wcwidth is\n");
  printf("// not 1 in the Ubuntu 24.04 C.UTF-8 locale. Code points not covered\n");
  printf("// here are width 1. The intervals are sorted and non-overlapping.\n");
  printf("var wcwidthRanges = [...]wcwidthRange{\n");

  int previous = wcwidth(0);
  unsigned int start = 0;
  for (unsigned int code_point = 1; code_point <= 0x10FFFF; code_point++) {
    int width = wcwidth((wchar_t)code_point);
    if (width < -1 || width > 2) {
      fprintf(stderr, "unexpected wcwidth(%d) = %d\n", code_point, width);
      return 1;
    }
    if (width == previous) {
      continue;
    }
    if (previous != 1) {
      printf("\t{0x%04X, 0x%04X, %d},\n", start, code_point - 1, previous);
    }
    start = code_point;
    previous = width;
  }
  if (previous != 1) {
    printf("\t{0x%04X, 0x%04X, %d},\n", start, 0x10FFFF, previous);
  }
  printf("}\n");
  return 0;
}
